import axios from "axios";
import MaterialTable, { MTableToolbar } from "material-table";
import { Spinner } from "reactstrap";
import React, { Component } from "react";
import { Modal, ModalHeader, ModalBody } from "reactstrap";
import { connect } from "react-redux";
import PropTypes from "prop-types";
import { login, loadUser } from "../../actions/authActions";
import { clearErrors } from "../../actions/errorActions";
import store from "../../store";
import { Button } from "@material-ui/core";

class UserAccessModal extends Component {
  state = {
    modal: false,
    rowData: [],
    tableLoaded: false,

    columns: [
      { title: "ID", field: "id", editable: "never" },
      { title: "Name", field: "name" },
      {
        title: "Created By",
        field: "created_by",
        editable: "never",
        initialEditValue: this.props.auth.isAuthenticated
          ? this.props.auth.user.name
          : "Guest"
      }
    ]
  };
  componentDidMount() {
    this.retrieveFromDb();
  }
  toggle = () => {
    this.setState({
      modal: !this.state.modal
    });
  };
  retrieveFromDb = () => {
    this.setState(state => ({
      tableLoaded: false,
      rowData: state.rowData
    }));
    axios
      .get("/api/clients")
      .then(res => {
        var rowData;
        if (!this.state.showDeletes) {
          rowData = res.data.filter((x, index) => {
            return x.deletedAt == null;
          });
          rowData = rowData.map((x, index) => {
            return {
              id: x._id,
              name: x.name,
              created_by: x.createdByUserId.name,
              deleted_at: x.deletedAt
            };
          });
        } else {
          rowData = res.data.map((x, index) => {
            return {
              id: x._id,
              name: x.name,
              created_by: x.createdByUserId.name,
              deleted_at: x.deletedAt
            };
          });
        }

        this.setState(state => ({
          tableLoaded: true,
          rowData
        }));
      })
      .catch(err => console.log(err));
  };

  render() {
    return (
      <div>
        <Button
          className="mt-2 mb-3"
          variant="contained"
          color="primary"
          onClick={this.toggle}
        >
          Assign Users
        </Button>
        <Modal size={"lg"} isOpen={this.state.modal} toggle={this.toggle}>
          <ModalHeader toggle={this.toggle}>Login</ModalHeader>
          <ModalBody>
            {this.state.tableLoaded ? (
              <MaterialTable
                columns={this.state.columns}
                data={this.state.rowData}
                title="Clients"
                options={{
                  actionsColumnIndex: 4,
                  addRowPosition: "first",
                  exportButton: true,
                  exportFileName: "Clients",
                  rowStyle: rowData => ({
                    backgroundColor:
                      rowData.deleted_at === null ? "#EEE" : "#FFF"
                  })
                }}
                onRowClick={(rowdata, event) => {
                  this.onPageChangeClick(
                    "ClientsNav",
                    "ClientsConfiguration",
                    event.id
                  );
                  //console.log(rowdata);
                }}

                //////
              />
            ) : (
              <div
                style={{
                  display: "flex",
                  justifyContent: "center"
                }}
              >
                <Spinner animation="border" />
              </div>
            )}
          </ModalBody>
        </Modal>
      </div>
    );
  }
}

const mapStateToProps = state => ({
  isAutheticated: state.auth.isAutheticated,
  error: state.error
});

export default connect(mapStateToProps, null)(UserAccessModal);
//mapStateToProps gets state variables from elsewhere in the app.
//the stuff in the curly braces are methods brought in to modify state in other parts of the app
//all these things will be declared in the component props
